-- SALY FONDEO LEG-03 and LEG-05 / C2 additional source-specific finding; no other schemas, no legal authorization.
BEGIN;
DO $p$ BEGIN
 IF (SELECT COUNT(*) FROM saly.programas_investigacion p JOIN saly.proyecto pr ON pr.id=p.proyecto_id WHERE p.codigo='SALY_FONDEO_LEGAL' AND pr.codigo='SALY-001') <> 1 THEN RAISE EXCEPTION 'BLOCK_SALY_PROGRAM'; END IF;
 IF (SELECT COUNT(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id WHERE u.codigo='SALY-LEG-05' AND c.codigo='C2' AND c.estado='EN_CURSO')<>1 THEN RAISE EXCEPTION 'BLOCK_LEG05_C2_DRIFT'; END IF;
 IF (SELECT COUNT(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id WHERE u.codigo='SALY-LEG-03' AND c.codigo='C2' AND c.estado='PENDIENTE')<>1 THEN RAISE EXCEPTION 'BLOCK_LEG03_C2_DRIFT'; END IF;
 IF EXISTS(SELECT 1 FROM saly.evidencias WHERE codigo='SALY-EVD-LEG-05-C2-SBS-20261021') THEN RAISE EXCEPTION 'BLOCK_EVIDENCE_ALREADY_PRESENT'; END IF;
 IF (SELECT COUNT(*) FROM saly.escenarios WHERE codigo IN ('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014') AND NOT ((parametros->'evaluacion_legal') ? 'sbs_actividad_empleador_matriz'))<>4 THEN RAISE EXCEPTION 'BLOCK_SALY_SCENARIO_DRIFT'; END IF;
END $p$;
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado)
VALUES('SALY-EVD-LEG-05-C2-SBS-20261021','ANALISIS_APLICADO_REGULATORIO',
 'Interpretación preliminar SBS 650-2024: préstamos al personal y obligación UIF',
 'SBS define prestamistas dedicados con fondos propios, sin excepción expresa por destino exclusivos empleados ni umbral mensual. Boletín UIF 152: no existe diligencia simplificada para prestamistas obligados. Requiere clasificación de actividad y consulta SBS; ENAPU es antecedente laboral no exención. No dictamen APTO.',
 'SBS 650-2024; UIF 152 p.8; SBS sujetos obligados y consulta; ENAPU politica préstamos 2024; TC descuentos; SUNAT art26.',
 DATE '2026-10-21','{"schema":"saly.legal_regulatory_applicability/v1","jurisdiction":"Peru","program":"SALY_FONDEO_LEGAL","fecha":"2026-10-21","stage":"C2_APLICADO_EN_CURSO","legal_authorization":false,"registration_exemption_proven":false,"independent_C3_done":false,"contract_fact":"SALY business: trabajador recibe un préstamo, trabajador debe devolverlo, descuento por planilla autorizado; ruta A empresa es acreedor y SALY presta únicamente servicios SaaS; no confundir con pago de salarios.","issue":"Definir si préstamos internos, recurrentes y exclusivos a empleados con recursos de empleador principal no financiero y plataforma SaaS constituyen ''empresa dedicada a otorgar préstamos'' según SBS 650-2024 artículo 2.b.","official_sources":[{"url":"https://www.sbs.gob.pe/Portals/0/Archivos/super_registros/Resolucion-SBS-N-650-2024.pdf","authority":"SBS","norm":"Resolucion SBS 650-2024","articles":["1","2.b","2.c","2.d","3","4","6","7","9"],"verified":"2026-10-21","finding":"Registro previo y obligatorio de empresas DEDICADAS a prestar con fondos propios a clientes, inclusive mediante plataforma; tasa de inscripción 0 y vigencia indeterminada. No hay regla literal de excepción solo trabajadores ni umbral transacciones."},{"url":"https://www.sbs.gob.pe/Portals/5/jer/BOLETIN-INFORMATIVOS/2025/BOLETIN%20UIF%20N%C2%B0%20152.pdf","authority":"SBS UIF","norm":"Boletin UIF 152 (2025)","pages":[8],"verified":"2026-10-21","finding":"Para empresas de prestamos sujetas a UIF no existe regimen simplificado de debida diligencia; debe aplicarse a todos clientes aunque operaciones bajo umbral; regímenes general y reforzado según caso."},{"url":"https://www.sbs.gob.pe/prevencion-de-lavado-activos/sujetos-obligados","authority":"SBS UIF","norm":"Sujetos obligados y sus obligaciones","verified":"2026-10-21","finding":"SPLAFT, oficial de cumplimiento y deberes de identificación, registros y ROS según obligaciones que correspondan. Canal de consultas supervisionuif."},{"url":"https://www.sbs.gob.pe/supervisados-y-registros/registros/otros-registros/casas-de-cambio-prestamos-y-empenos/informacion-sobre-registro-de-casas-de-cambio-prestamos-y-o-empenos","authority":"SBS","norm":"Información de registro SBS","verified":"2026-10-21","finding":"Registro público, inscripción y sanciones; canal consultasoc y teléfono oficial"},{"url":"https://www.enapu.com.pe/sistema-transparencia/views/documentos/1551212393.jj.pdf","authority":"ENAPU","norm":"Politica de prestamos personal PL-POPP ENAPU-001-2024","verified":"2026-10-21","finding":"Empresa estatal no financiera documenta préstamos por política interna y descuento mensual; 30 por ciento es tope de política ENAPU y NO universal. Este antecedente no acredita clasificación SBS de una empresa privada SALY."},{"url":"https://www.tc.gob.pe/jurisprudencia/2025/02275-2023-AA.html","authority":"Tribunal Constitucional","norm":"STC 02275-2023-PA/TC","verified":"2026-10-21","finding":"Autorizaciones de descuentos privados no pueden contradecir protección de remuneración; caso de créditos cooperativos, no sentencia específica de préstamo patronal directo."},{"url":"https://iat.sunat.gob.pe/sites/default/files/documentos/2023/09/archivos/fundimprentapn.pdf","authority":"SUNAT","norm":"Art. 26 LIR","verified":"2026-10-21","finding":"Excepciones específicas a presunción intereses en préstamos al personal por adelanto de sueldo (hasta 1 UIT) y convenios colectivos; NO es techo de crédito ni exención SBS."}],"findings":["No existe evidencia suficiente para concluir que la exclusividad de empleados excluya inscripción; tampoco es correcto presumir que toda concesión incidental de crédito por empleador queda dentro del régimen SBS de empresa DEDICADA.","La operación recurrente automatizada aumenta el riesgo de encaje SBS, pero la norma no fija cantidad o porcentaje que por sí solos active registro.","Para un sujeto obligado inscrito, registro gratuito no equivale a cumplimiento gratuito; SBS UIF 2025 descarta debida diligencia simplificada para las empresas de préstamos.","Política ENAPU evidencia préstamo laboral interno pero no genera exención para privados ni tope legal universal 30% de sueldo.","La autorización de planilla no sustituye control de capacidad y salario protegido. El origen del capital y acreedor determinan quién asume obligaciones.","En C y D deben evaluarse por separado préstamo habitual de SALY y actividad real del empleador comprador/financiador."],"criteria":[{"key":"actividad_empresarial","question":"¿Se dedica el empleador a una actividad de préstamo o constituye un beneficio accesorio aislado a su giro?","proof":"Política de préstamos, contrato social, registro de ingresos, beneficiarios exclusivamente trabajadores, periodicidad, publicidad, cuantía, costos y estructura"},{"key":"acreedor_efectivo","question":"¿Quién aparece como prestamista y titular del crédito al nacimiento, y cómo se prueba?","proof":"Mutuo individual, estado de cuenta, desembolso, cupo, cuenta bancaria, autorización planilla, facturación"},{"key":"recursos_propios","question":"¿Los fondos son propios sin captación de terceros?","proof":"Estado bancario, presupuesto, contabilidad origen fondos, contrato con SALY"},{"key":"saly_facultades","question":"¿SALY es solo SaaS o decide/practica crédito, custodia y cobranza propia?","proof":"Contrato plataforma y mandato, políticas de decisión, flujos y APIs bancarias"},{"key":"sbs_y_uif","question":"¿SBS considera a la empresa sujeto obligado/registrable a pesar de uso exclusivo trabajadores?","proof":"Consulta escrita y respuesta oficial, junto con dictamen de abogado y contrato del caso"}],"branch_decision":[{"if":"NO_SBS_650_APLICA_A_BENEFICIO_ACCESORIO","then":"A: empresa puede prestar con política propia, contrato trabajador-empresa, cuenta empresaria y SALY SaaS; mantener límites de descuento, datos y fiscalidad","condition":"Documento SBS o dictamen independiente sustentado, estatuto y flujos reales"},{"if":"SBS_650_APLICA_A_ACTIVIDAD_EMPRESA_PRESTAMOS","then":"A: empresa debe estar inscrita previamente y cumplir SPLAFT/UIF, conocimiento de todos clientes, OC y demás obligaciones aplicables; SALY SaaS puede automatizar, no desplaza al obligado","condition":"Analizar presupuesto y aceptación del empleador; no describir registro como licencia bancaria"},{"if":"EXENCION_NO_ACREDITADA","then":"Mantener A sin activación bajo presunción de exención. Comparar C y D sin suponer que cesión o un mutuo B2B esquivan el régimen por sí solos","condition":"No emitir APTO definitivo"}],"authority_consultation":{"channel":"consultasupervisionuif@sbs.gob.pe","alternate":"consultasoc@sbs.gob.pe","sent":false,"purpose":"Criterio de sujeción al registro/UIF de empleador no financiero prestando solo a su personal con capital propio vía SaaS externo.","questions":["En una empresa industrial, minera o de servicios cuyo objeto principal no es financiero, ¿el programa accesoriamente aprobado de mutuos exclusivos para sus empleados con sus propios fondos califica como empresa dedicada a préstamos Res 650-2024 art2.b?","¿Cambia el análisis por operar de forma recurrente, todos los meses y mediante aplicación de tercero SaaS que no custodia fondos ni es acreedor?","¿Existen umbrales, criterios de habitualidad o indicios de actividad dedicada aplicables? Señalar fundamentos concretos.","En caso de aplicabilidad, ¿qué deberes de registro/UIF/PLAFT/OC corresponden al empleador frente a la plataforma SaaS y qué trámites previos requiere?","¿Cómo se clasifica, para fines del registro, que empleador compre sistemáticamente derechos de cobro emitidos por SALY en lugar de prestar directamente?"],"attachments_to_prepare":["Diagrama de pagos y titularidad caso A","Estatutos/poderes y actividad real empleador piloto","Modelo contrato empleador-SALY SaaS y mutuo al trabajador","Política interna, límites y autorizaciones de planilla"],"consultation_reply_received":false},"cost_assessment":{"fee_registration_sbs_pen":0,"fee_registration_source":"Art. 6 Res SBS 650-2024","oc_labor_cost_pen":null,"know_your_customer_pen_per_user":null,"monitoring_reporting_pen":null,"compliance_audit_pen":null,"legal_advice_pen":null,"data_privacy_pen":null,"payroll_control_pen":null,"regulatory_cost_total_pen":null,"note":"NULL indica por cotizar. No asumir cumplimiento UIF nulo por ser personal de empresa; no asumir que este se aplica si el empleador no encaja en la categoria."},"final_status":"EN_INVESTIGACION_CONSULTA_AUTORIDAD_PENDIENTE","expected_next":"C2 resolver por rama, costo legal, contratos, documentación de caso y respuesta SBS/abogado; revisar C3 independiente, no autorizacion operacional."}'::jsonb,'VIGENTE');
INSERT INTO saly.checkpoint_evidencias(checkpoint_id,evidencia_id,tipo_relacion)
SELECT c.id,e.id,'SBS_APLICACION_C2_EN_CURSO'
FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON c.unidad_id=u.id
JOIN saly.evidencias e ON e.codigo='SALY-EVD-LEG-05-C2-SBS-20261021'
WHERE u.codigo IN('SALY-LEG-03','SALY-LEG-05') AND c.codigo='C2';
UPDATE saly.checkpoints_investigacion c SET estado='EN_CURSO',
 nota_revision='C2 aplica SBS Res650-2024 y Boletín UIF 152 a esquema de empleador interno. Pendiente encaje específico/consulta SBS, contratos, costos. No PASS ni permiso.',
 actualizado_en=now()
FROM saly.unidades_investigacion u WHERE c.unidad_id=u.id AND u.codigo='SALY-LEG-03' AND c.codigo='C2' AND c.estado='PENDIENTE';
UPDATE saly.unidades_investigacion SET estado_trabajo='EN_CURSO',actualizado_en=now()
WHERE codigo='SALY-LEG-03' AND estado_trabajo='PENDIENTE';
UPDATE saly.escenarios s
SET parametros=jsonb_set(s.parametros,'{evaluacion_legal,sbs_actividad_empleador_matriz}',r.payload,true),updated_at=now()
FROM (VALUES
('SALY-ESC-011','{"code":"SALY-ESC-011","registration_question":"¿Prestamista empleador interno dedicado o accesorio?","activity":"MUTUO_EMPRESA_TRABAJADOR","branch_impact":"Dos ramas directas. Si registro obligatorio, empleador cumple UIF y SALY sigue SaaS; si no, operar beneficio privado cumpliendo planilla y tributos.","legal_status":"SIN_DICTAMEN_C2_CONDICIONAL","source":"SALY-EVD-LEG-05-C2-SBS-20261021","evidence":"SBS 650-2024 art2.b y 3/6; Boletín UIF 152 p8; ENAPU; TC","no_automatic_legal_exemption":true}'::jsonb),
('SALY-ESC-012','{"code":"SALY-ESC-012","registration_question":"¿Empleador es prestamista registrable y SALY mandatario/custodio regulado?","activity":"MUTUO_EMPRESA_TRABAJADOR_CON_ADMINISTRACION","branch_impact":"Misma rama empleador A más analizar titularidad/custodia; mandato no neutraliza registro ni riesgo.","legal_status":"SIN_DICTAMEN_C2_CONDICIONAL","source":"SALY-EVD-LEG-05-C2-SBS-20261021","evidence":"SBS 650-2024 art2.b y 3/6; Boletín UIF 152 p8; ENAPU; TC","no_automatic_legal_exemption":true}'::jsonb),
('SALY-ESC-013','{"code":"SALY-ESC-013","registration_question":"¿SALY originadora registrable? ¿Empresa adquirente habitual de créditos sujetos a otra obligación?","activity":"CESION_CONTEMPORANEA_EMPRESA","branch_impact":"No atribuir por defecto al empleador registro de préstamo directo; analizar compraventa sistemática distinta, y registro SALY originador.","legal_status":"SIN_DICTAMEN_C2_CONDICIONAL","source":"SALY-EVD-LEG-05-C2-SBS-20261021","evidence":"SBS 650-2024 art2.b y 3/6; Boletín UIF 152 p8; ENAPU; TC","no_automatic_legal_exemption":true}'::jsonb),
('SALY-ESC-014','{"code":"SALY-ESC-014","registration_question":"¿Empresa prestamista B2B a SALY es actividad dedicada? ¿SALY prestamista empleados necesita registro?","activity":"MUTUO_EMPRESA_SALY_Y_SALY_TRABAJADOR","branch_impact":"Doble examen de actividad. No se transfiere presunción LIR de préstamo de personal al mutuo corporativo.","legal_status":"SIN_DICTAMEN_C2_CONDICIONAL","source":"SALY-EVD-LEG-05-C2-SBS-20261021","evidence":"SBS 650-2024 art2.b y 3/6; Boletín UIF 152 p8; ENAPU; TC","no_automatic_legal_exemption":true}'::jsonb)
) AS r(codigo,payload)
WHERE s.codigo=r.codigo AND s.estado='BORRADOR' AND s.parametros->>'familia'='MODELOS_FONDEO_TRIBUTOS';
DO $v$ BEGIN
 IF (SELECT COUNT(*) FROM saly.checkpoint_evidencias ce JOIN saly.evidencias e ON e.id=ce.evidencia_id WHERE e.codigo='SALY-EVD-LEG-05-C2-SBS-20261021')<>2 THEN RAISE EXCEPTION 'BLOCK_LINK_COUNT'; END IF;
 IF (SELECT COUNT(*) FROM saly.escenarios WHERE codigo IN('SALY-ESC-011','SALY-ESC-012','SALY-ESC-013','SALY-ESC-014')
 AND parametros->'evaluacion_legal'->'sbs_actividad_empleador_matriz'->>'no_automatic_legal_exemption'='true'
 AND parametros->'evaluacion_legal'->>'dictamen_final' IS NULL
 AND parametros->'validacion'->>'legal'='PENDIENTE')<>4 THEN RAISE EXCEPTION 'BLOCK_SALY_MATRIX_READBACK'; END IF;
 IF (SELECT COUNT(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id
 WHERE u.codigo IN('SALY-LEG-03','SALY-LEG-05') AND c.codigo='C2' AND c.estado='EN_CURSO' AND c.dictamen_revision IS NULL)<>2 THEN RAISE EXCEPTION 'BLOCK_C2_NOT_IN_PROGRESS'; END IF;
 IF (SELECT COUNT(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id
 JOIN saly.programas_investigacion p ON p.id=u.programa_id
 WHERE p.codigo='SALY_FONDEO_LEGAL' AND c.estado='DONE')<>5 THEN RAISE EXCEPTION 'BLOCK_DONE_COUNT_DRIFT'; END IF;
END $v$;
COMMIT;